// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testFuzz_property(address ownerCandidate, address other) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(other != ownerCandidate);

        c.transferOwnership(ownerCandidate);

        vm.prank(ownerCandidate);
        c.NETM();

        assertTrue(c.balanceOf(ownerCandidate) == c.totalDistributed());
    }
}
